<script setup lang="ts">
import { computed, onUnmounted, ref, watch } from 'vue'
import { api, ApiError } from '../api'
import type { Ingredient, Recipe, StatusDeletion } from '../types'
import { productTitle, toast, verificationLabels } from '../utils'
import ItemPicker from './ItemPicker.vue'
import ConflictDialog from './ConflictDialog.vue'
import RevisionPanel from './RevisionPanel.vue'
import SettingLinks from './SettingLinks.vue'
import RecordOptionSelect from './RecordOptionSelect.vue'
const props = defineProps<{ recipe: Recipe; index: number }>()
const emit = defineEmits<{ changed: []; copy: [fields: Record<string, unknown>]; dirty: [value: boolean] }>()
const clone = (value: Recipe): Recipe => JSON.parse(JSON.stringify(value))
const form = ref(clone(props.recipe)); const open = ref(!props.recipe.ingredients.length || location.hash === `#${props.recipe.id}`); const choosing = ref(false); const busy = ref(false); const error = ref(''); const remote = ref(false); const history = ref(false); const conflict = ref<{ current: Recipe; submitted: Record<string, unknown> }>()
function payload() { return { name: form.value.name, output_quantity: form.value.output_quantity, notes: form.value.notes, verification: form.value.verification, development_status: form.value.development_status, ingredients: form.value.ingredients.map(i => ({ product_id: i.product_id, category: i.category, quantity: i.quantity })) } }
const saved = ref(JSON.stringify(payload())); const dirty = computed(() => JSON.stringify(payload()) !== saved.value)
const formula = computed(() => form.value.ingredients.map(i => `${i.category ? `任意${i.category}` : i.item ? productTitle(i.item) : '未选择物品'} ×${i.quantity}`).join(' ＋ ') || '材料待补充')
function apply(value: Recipe) { form.value = clone(value); saved.value = JSON.stringify(payload()); remote.value = false }
watch(() => props.recipe, value => { if (dirty.value) { if (value.version !== form.value.version) remote.value = true } else apply(value) }); watch(dirty, value => emit('dirty',value)); onUnmounted(() => emit('dirty',false))
function add(ingredient: Ingredient) { const existing = form.value.ingredients.find(i => i.product_id === ingredient.product_id && i.category === ingredient.category); if (existing) { existing.quantity++; toast('已合并相同材料的数量') } else form.value.ingredients.push(ingredient); choosing.value = false }
async function save() { busy.value = true; error.value = ''; try { apply(await api<Recipe>(`/recipes/${form.value.id}`,{ method: 'PATCH', body: JSON.stringify({ ...payload(), version: form.value.version }) })); emit('changed'); toast('配方已保存') } catch (e) { if (e instanceof ApiError && e.status === 409 && e.details?.current) conflict.value = { current: e.details.current, submitted: payload() }; else error.value = (e as Error).message } finally { busy.value = false } }
function statusDeleted(result: StatusDeletion) {
  if (dirty.value && form.value.development_status === result.id) {
    form.value.development_status = result.replacement
    form.value.development_status_label = result.replacement_label
  }
  emit('changed')
}
function useServer() { if (conflict.value) apply(conflict.value.current); conflict.value = undefined }
async function merge() { if (!conflict.value) return; form.value.version = conflict.value.current.version; conflict.value = undefined; await save() }
async function remove() { if (!confirm('将这套配方移入回收站？产物和其他配方会保留。')) return; busy.value = true; error.value = ''; try { await api(`/recipes/${form.value.id}`,{ method: 'DELETE', body: JSON.stringify({ version: form.value.version }) }); saved.value = JSON.stringify(payload()); emit('dirty',false); emit('changed') } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
</script>
<template><article :id="recipe.id" class="panel recipe-editor"><button type="button" class="recipe-summary" :aria-expanded="open" @click="open = !open"><span><strong>{{ open ? '▾' : '▸' }} {{ form.name || `配方 ${index + 1}` }}</strong><small>{{ formula }} → 产物 ×{{ form.output_quantity }}</small></span><span class="tag">{{ !form.ingredients.length ? '待补充' : verificationLabels[form.verification] }}</span><span v-if="dirty" class="unsaved-dot">未保存</span></button><div v-if="open" class="recipe-body"><p v-if="remote" class="ai-status">这套配方已有新修改，保存时会展示差异。</p><form @submit.prevent="save"><label>配方名称（可留空）<input v-model="form.name" maxlength="160" placeholder="例如：基础配方、替代材料方案" /></label><span class="field-label">合成材料</span><div v-for="(ingredient,at) in form.ingredients" :key="`${ingredient.product_id}:${ingredient.category}`" class="ingredient-row"><div><strong>{{ ingredient.category ? `任意${ingredient.category}` : ingredient.item ? productTitle(ingredient.item) : '物品待补充' }}</strong><small class="muted">{{ ingredient.category ? '分类材料' : ingredient.item?.item_kind === 'tool' ? '道具' : '商品' }}<span v-if="ingredient.item?.deleted_at" class="danger-text"> · 已删除，可恢复或更换材料</span></small></div><label>数量<input v-model.number="ingredient.quantity" type="number" min="1" max="1000000000" step="1" required :aria-label="`材料 ${at+1} 数量`" /></label><button type="button" class="text-button danger-text" @click="form.ingredients.splice(at,1)">移除</button></div><p v-if="!form.ingredients.length" class="muted">材料尚未填写，可先保留为待补充配方。</p><button type="button" class="secondary small" @click="choosing = true">＋ 添加材料</button><div class="field-inline recipe-options"><label>产出数量<input v-model.number="form.output_quantity" type="number" min="1" max="1000000000" step="1" required /></label><label>验证情况<select v-model="form.verification" aria-label="验证情况"><option v-for="(label,key) in verificationLabels" :key="key" :value="key">{{ label }}</option></select></label></div><div class="field"><span class="field-label">制作状态</span><RecordOptionSelect v-model="form.development_status" kind="statuses" label="制作状态" :fallback="form.development_status_label" :update-on-delete="false" @status-deleted="statusDeleted" /></div><label>条件／备注<textarea v-model="form.notes" rows="3" maxlength="100000" placeholder="地点、工具、顺序、试验记录等"></textarea></label><p v-if="error" class="error-text" role="alert">{{ error }}</p><div class="form-actions"><button class="primary" :disabled="busy || !dirty">{{ busy ? '保存中…' : dirty ? '保存这套配方' : '已保存' }}</button><button type="button" class="secondary small" :disabled="busy" @click="emit('copy',payload())">复制配方</button><button type="button" class="text-button" @click="history = !history">修改历史</button><button type="button" class="text-button danger-text" :disabled="busy" @click="remove">移入回收站</button></div></form><details class="supplement"><summary>关联灵感</summary><SettingLinks kind="recipe" :id="recipe.id" /></details><RevisionPanel v-if="history" kind="recipe" :id="recipe.id" :version="form.version" @restored="saved = JSON.stringify(payload()); emit('changed')" /></div><ItemPicker v-if="choosing" title="选择材料" allow-category @select="add" @cancel="choosing = false" /><ConflictDialog v-if="conflict" :current="conflict.current" :submitted="conflict.submitted" @server="useServer" @merge="merge" @cancel="conflict = undefined" /></article></template>
